long long countVowels(std::string text) {
    long long total = 0;
    for (std::size_t i = 0; i < text.size(); ++i) {
        char c = (char)std::tolower((unsigned char)text[i]);
        if (c=='a'||c=='e'||c=='i'||c=='o'||c=='u') ++total;
    }
    return total;
}

